/// Specifies the (Grid,Cell) intersection of each interval of the representation, if any.
/// 
/// The information allows you to locate, on one or several grids, the intersection of volume (cells) and surface (faces) elements with a wellbore trajectory (existing or planned), streamline trajectories, or any polyline set.
#[derive(Debug, Default, Clone, PartialEq, EnergymlObject)]
#[energyml(
    package = "resqml",
    version = "2.2_dev3",
    xml_name = "IntervalGridCells"
)]
pub struct IntervalGridCells {
    /// The number of non-null entries in the grid indices array.
    #[energyml(elem, xml_name = "CellCount", min_inclusive = "1")]
    pub cell_count: i64,

    /// Size of array = IntervalCount.
    /// Null values signify that interval is not within a grid.
    /// BUSINESS RULE: The cell count must equal the number of non-null entries in this array.
    #[energyml(elem, xml_name = "GridIndices", min = 1)]
    pub grid_indices: Option<energyml_eml_2_2::AbstractIntegerArray>,

    /// The cell index for each interval of a representation. The grid index is specified by grid index array, to give the (Grid,Cell) index pair.
    /// 
    /// BUSINESS RULE: Array length must equal cell count.
    #[energyml(elem, xml_name = "CellIndices", min = 1)]
    pub cell_indices: Option<energyml_eml_2_2::AbstractIntegerArray>,

    /// For each cell, these are the entry and exit intersection faces of the trajectory in the cell. Use null for missing intersections, e.g., when a trajectory originates or terminates within a cell. The local face-per-cell index is used because a global face index need not have been defined on the grid.
    /// 
    /// BUSINESS RULE: The array dimensions must equal 2 x CellCount.
    #[energyml(elem, xml_name = "LocalFacePairPerCellIndices", min = 1)]
    pub local_face_pair_per_cell_indices: Option<energyml_eml_2_2::AbstractIntegerArray>,

    #[energyml(elem, xml_name = "Grid", min = 1)]
    pub grid: Vec<energyml_eml_2_2::DataObjectReference>,

}

/// A mapping from intervals to stratigraphic units for representations (grids or wellbore frames). Since a single interval may corresponds to several units, the mapping is done using a jagged array.
#[derive(Debug, Default, Clone, PartialEq, EnergymlObject)]
